<div class="page-head"><div><p class="eyebrow">OFERTAS EXTERNAS · VIGENCIA</p><h1>Cotizaciones</h1><p class="muted">Cada oferta se relaciona con proveedor y producto mediante selects.</p></div><a class="boton boton--primario" href="<?= site_url('cotizaciones/nueva') ?>">Nueva cotización <span>＋</span></a></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Proveedor</th><th>Emitida</th><th>Válida hasta</th><th>Productos</th><th>Estado</th></tr></thead><tbody><?php if ($cotizaciones === []): ?><tr><td colspan="5" class="empty">No hay cotizaciones.</td></tr><?php endif; ?><?php foreach ($cotizaciones as $cotizacion): ?><tr><td><strong><?= esc($cotizacion['razon_social']) ?></strong></td><td><?= esc(date('d/m/Y', strtotime($cotizacion['fecha_emision']))) ?></td><td><?= esc(date('d/m/Y', strtotime($cotizacion['valida_hasta']))) ?></td><td><?= (int) $cotizacion['productos'] ?></td><td><span class="pill pill--<?= strtolower($cotizacion['estado']) === 'vigente' ? 'ok' : 'muted' ?>"><?= esc($cotizacion['estado']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section><?= $this->endSection() ?>
